package com.hmdp.ai.domain.knowledge;

import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;

public final class ChunkingPolicy {private final String strategy;private final int maxChars,minChars,overlapChars;private final boolean preserveHeading,parentChildEnabled,semanticBoundaryEnabled;private final String tableStrategy;public ChunkingPolicy(String strategy,int maxChars,int minChars,int overlapChars,boolean preserveHeading,boolean parentChildEnabled,String tableStrategy,boolean semanticBoundaryEnabled){if(maxChars<=0||minChars<=0||overlapChars<0||overlapChars>=maxChars||minChars>maxChars)throw new IllegalArgumentException("chunking policy limits are invalid");this.strategy=strategy;this.maxChars=maxChars;this.minChars=minChars;this.overlapChars=overlapChars;this.preserveHeading=preserveHeading;this.parentChildEnabled=parentChildEnabled;this.tableStrategy=tableStrategy;this.semanticBoundaryEnabled=semanticBoundaryEnabled;}public static ChunkingPolicy parse(String json,ObjectMapper mapper){try{JsonNode n=mapper.readTree(json);return new ChunkingPolicy(n.path("strategy").asText("RECURSIVE"),n.path("maxChars").asInt(800),n.path("minChars").asInt(120),n.path("overlapChars").asInt(80),n.path("preserveHeading").asBoolean(true),n.path("parentChildEnabled").asBoolean(false),n.path("tableStrategy").asText("ROW"),n.path("semanticBoundaryEnabled").asBoolean(false));}catch(Exception e){throw new IllegalArgumentException("chunking policy is invalid",e);}}public String getStrategy(){return strategy;}public int getMaxChars(){return maxChars;}public int getMinChars(){return minChars;}public int getOverlapChars(){return overlapChars;}public boolean isPreserveHeading(){return preserveHeading;}public boolean isParentChildEnabled(){return parentChildEnabled;}public String getTableStrategy(){return tableStrategy;}public boolean isSemanticBoundaryEnabled(){return semanticBoundaryEnabled;}}
